const API='https://api.YOUR-TENNIS-LIVE-PROVIDER.com/v1'; // PLACEHOLDER - no live provider wired yet
const KEY='REPLACE_WITH_YOUR_TENNIS_API_KEY';
const TZ='Europe/Sofia';

// v1.0 DRAFT thresholds. These are NOT fitted from data - the source document gives one
// worked example (Nadal vs Fognini), not a dataset. Refit MIN_DEUCE_RATE and
// MIN_SERVICE_SAMPLE against your own backtest of historical finals/semifinals before
// trusting this for anything beyond "worth watching." See the sticky note above.
const CFG={
  FINAL_ROUNDS:['F','SF','FINAL','SEMIFINAL'],           // criterion 1: final or semifinal only
  MIN_GAMES_OBSERVED:5,                                  // criterion 2: "watch 5-6 games" before acting
  MIN_SERVICE_SAMPLE:2,                                  // need at least this many completed service games
                                                          // for THIS server in THIS match before trusting their rate
  MIN_DEUCE_RATE:0.60,                                   // fraction of that server's own service games so far
                                                          // that went to 40:40 - UNVALIDATED GUESS, tune via backtest
  SMALL_SAMPLE_WARNING_BELOW:4,                          // flag alerts built on fewer than this many service games
  STAKE_NOTE_EUR:20                                      // flat, fixed stake suggested in the alert - never progressive
};

const H={Authorization:'Bearer '+KEY,Accept:'application/json'};

async function getLiveMatches(){
  // Expected shape (adapt to your chosen provider's real response):
  // [{ id, round:'F'|'SF'|..., status:'live'|'finished'|'scheduled',
  //    playerA, playerB, server:'A'|'B',
  //    games:[{ setNumber, gameNumber, server:'A'|'B', wentToDeuce:boolean, winner:'A'|'B' }, ...] }]
  return await this.helpers.httpRequest({method:'GET',url:API+'/matches/live',headers:H,json:true,timeout:15000});
}

function serverStats(games, server){
  const served = games.filter(g => g.server === server);
  const deuces = served.filter(g => g.wentToDeuce).length;
  return {
    gamesServed: served.length,
    deuceCount: deuces,
    deuceRate: served.length ? deuces / served.length : 0
  };
}

let matches = [];
try {
  matches = await getLiveMatches.call(this);
} catch (e) {
  return [{ json: { error: true, message: 'Live provider call failed: ' + (e?.message || String(e)), engineVersion: 'TENNIS_4040_MONITOR_V1_0_DRAFT' } }];
}

const alerts = [];
for (const m of (matches || [])) {
  if (m.status !== 'live') continue;
  if (!CFG.FINAL_ROUNDS.includes(String(m.round || '').toUpperCase())) continue;
  const games = m.games || [];
  if (games.length < CFG.MIN_GAMES_OBSERVED) continue;

  const currentServer = m.server;
  if (currentServer !== 'A' && currentServer !== 'B') continue;

  const stats = serverStats(games, currentServer);
  if (stats.gamesServed < CFG.MIN_SERVICE_SAMPLE) continue;
  if (stats.deuceRate < CFG.MIN_DEUCE_RATE) continue;

  alerts.push({
    isAlert: true,
    matchId: m.id,
    round: m.round,
    playerA: m.playerA,
    playerB: m.playerB,
    server: currentServer,
    serverName: currentServer === 'A' ? m.playerA : m.playerB,
    gamesObserved: games.length,
    serviceGamesSoFar: stats.gamesServed,
    deuceCount: stats.deuceCount,
    deuceRate: Number(stats.deuceRate.toFixed(2)),
    smallSample: stats.gamesServed < CFG.SMALL_SAMPLE_WARNING_BELOW,
    stakeNoteEur: CFG.STAKE_NOTE_EUR,
    engineVersion: 'TENNIS_4040_MONITOR_V1_0_DRAFT'
  });
}

if (!alerts.length) {
  return [{ json: { isAlert: false, engineVersion: 'TENNIS_4040_MONITOR_V1_0_DRAFT' } }];
}
return alerts.map(a => ({ json: a }));

const j=$json;if(!j.isAlert)return {json:j};
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const roundLabel = String(j.round||'').toUpperCase()==='F' ? 'Финал' : 'Полуфинал';
const lines=[
  `<b>🎾 40:40 НАБЛЮДАТЕЛ – ${esc(roundLabel)}</b>`,
  '',
  `<b>${esc(j.playerA)} — ${esc(j.playerB)}</b>`,
  `🏓 Следващ подавач: <b>${esc(j.serverName)}</b>`,
  `📊 ${j.deuceCount}/${j.serviceGamesSoFar} от неговите геймове на подаване стигнаха 40:40 (${Math.round(j.deuceRate*100)}%)`,
  '',
  `🎯 Възможна проверка: «Ще има 40:40 в гейма – Да» на следващото подаване на ${esc(j.serverName)}`,
  `💰 Предложен фиксиран залог: ${j.stakeNoteEur} EUR — без прогресия/догон`,
];
if (j.smallSample) lines.push('', '⚠️ Малка извадка (' + j.serviceGamesSoFar + ' гейма) – третирай като диагностика, не като сигурен сигнал.');
lines.push('', '❗ Невалидиран евристик – не е бактестван срещу исторически данни. Решението за залог е ръчно и на собствен риск.');
const text=lines.join('\n').trim();
return {json:{...j,text,telegram_text:text,engineVersion:'TENNIS_4040_MONITOR_V1_0_DRAFT'}};
